# Validate before Load so an invalid body is a 400, not masked by a 404.
validate:
  class: net.officefloor.hq.app.claim.ValidateRemind
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyRemind
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveRemind
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimReminded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.PathVariable;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;

public class ValidateRemind {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody RemindRequest request, Out<RemindRequest> body, Settings settings)
            throws ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        body.set(request);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

/** Reminds an OPEN or PENDING claim, once per sheet-today: its reminded date becomes the sheet's today. */
public class ApplyRemind {
    public void apply(@Val RemindRequest request, @Val Claim claim, Sheets sheets) throws ClaimStatusRefusedException {
        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
            throw new ClaimStatusRefusedException("Only an OPEN or PENDING claim can be reminded");
        }
        LocalDate today = sheets.today(claim.getSheetId());
        if (today.equals(claim.getRemindedOn())) {
            throw new ClaimStatusRefusedException("A claim can be reminded only once per sheet-today");
        }
        claim.setRemindedOn(today);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

public class SaveRemind {
    public void save(@Val Claim claim, Claims claims) {
        claims.remind(claim);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;

public class AuditClaimReminded {
    public void audit(@Val RemindRequest request, @Val Claim claim, People people, Audit audit) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        audit.recordOnCommit(ClaimAudit.line("REMIND", request.user(), person, claim, claim.getNumber()));
    }
}
package net.officefloor.hq.app.claim;

/** Body of POST /api/sheets/{sheetId}/claims/{claimId}/remind: who reminds the claim. */
public record RemindRequest(String user) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadClaim {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") String claimId,
            Claims claims, Out<Claim> claimOut) throws ClaimNotFoundException {
        Claim claim = null;
        try {
            claim = claims.find(sheetId, Long.parseLong(claimId));
        } catch (NumberFormatException e) {
            // not an id this app assigned
        }
        if (claim == null) {
            throw new ClaimNotFoundException(claimId);
        }
        claimOut.set(claim);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithClaim {
    public void respond(@Val Claim claim, ObjectResponse<ClaimResponse> response) {
        response.send(ClaimResponse.from(claim));
    }
}
-- A claim's tags: trimmed, lower-cased, repeats dropped, sorted and comma separated. Null: no tags.
